# 1. Footer: restore VPO (two replacements)
$footer = Get-ChildItem -Recurse -Filter "Footer.tsx" -ErrorAction SilentlyContinue |
          Where-Object { $_.FullName -notmatch "node_modules" } | Select-Object -First 1
if ($footer) {
    $t = [System.IO.File]::ReadAllText($footer.FullName, $enc)
    $changed = $false
    if ($t.Contains($f1_now)) { $t = $t.Replace($f1_now, $f1_back); $changed = $true }
    if ($t.Contains($f2_now)) { $t = $t.Replace($f2_now, $f2_back); $changed = $true }
    if ($changed) {
        [System.IO.File]::WriteAllText($footer.FullName, $t, $utf8NoBom)
        Write-Host ("OK Footer (VPO restored) -> " + $footer.FullName) -ForegroundColor Green
    } else {
        Write-Host "Footer: nothing to revert (maybe already has VPO)" -ForegroundColor Cyan
    }
} else { Write-Host "SKIP Footer: not found" -ForegroundColor Yellow }

# 2. Privacy: add GO-controller paragraph
$priv = Get-ChildItem -Recurse -Filter "page.tsx" -ErrorAction SilentlyContinue |
        Where-Object { $_.FullName -notmatch "node_modules" -and $_.FullName -match "privacy" } | Select-Object -First 1
if ($priv) {
    $t = [System.IO.File]::ReadAllText($priv.FullName, $enc)
    if ($t.Contains($p_new.Substring(0,40)) -and $t.Contains("33951844")) {
        Write-Host "ALREADY Privacy (GO paragraph present)" -ForegroundColor Cyan
    } elseif ($t.Contains($p_old)) {
        $t = $t.Replace($p_old, $p_new)
        [System.IO.File]::WriteAllText($priv.FullName, $t, $utf8NoBom)
        Write-Host ("OK Privacy (GO paragraph added) -> " + $priv.FullName) -ForegroundColor Green
    } else {
        Write-Host ("NOMATCH Privacy (anchor text differs) -> " + $priv.FullName) -ForegroundColor Yellow
    }
} else { Write-Host "SKIP Privacy: not found" -ForegroundColor Yellow }

